                v = Polyfill.DoubleToUInt64Bits(Polyfill.UInt64BitsToDouble(v) * 4503599627370496.0);
                e = (int)(v >> 52) - 0x3ff - 52;
            }
        }


        ReadOnlySpan<double> pow10 = [1, 10, 100, 1000, 10000, 100000, 1000000, 10000000, 100000000, 1000000000, 10000000000, 100000000000, 1000000000000, 10000000000000, 100000000000000, 1000000000000000, 10000000000000000, 1e+17, 1e+18, 1e+19, 1e+20, 1e+21, 1e+22, 0, 0, 0, 0, 0, 0, 0, 0, 0];
        ReadOnlySpan<ulong> pow10u = MemoryMarshal.Cast<double, ulong>(pow10);

        int n = (int)((0x267cfa2u * ((uint)e + 1)) >> 27);
        if (v == pow10u[n])
        {
            return n;
        }


        double h, l;
        (h, l) = log10Fast(e, v);

        const double err = 1.7205356741102976e-21;

        double left = h + (l - err), right = h + (l + err);
        if (left == right)
        {
            return left;
        }

        return log10Accurate(x);
    }
}
